window.kbPageData["views/entry/k-2dd879cdcaced5ff"] = {"key":"entry/k-2dd879cdcaced5ff","state":{"route":"entry/k-2dd879cdcaced5ff"},"node":{"id":"k-2dd879cdcaced5ff","mode":"k","title":"海南自由贸易港启动全岛封关运作","type":"事实与事件","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["open"],"主类":["事实与事件"],"出处性质":["机构注释"],"学科":["经济"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2025,"title":"海南自由贸易港启动全岛封关运作","slug":"4b299269da91"}],"directorySummary":"5.海南自由贸易港启动全岛封关运作\n全岛封关运作是海南自贸港建设的标志性工程，是进一步扩大开放的重要举措。封关是\n指将海南岛全岛建成一个海关监管特殊区域，实施以“‘一线’放开、‘二线’管住、岛\n内自由”为基本特征的自由化便利化政策制度。\n“‘一线’放开”，是将海南自贸港与我国关境外其他国家和地区之间…","sources":[{"id":"a89c1e9df6ffda2f","label":"海南自由贸易港启动全岛封关运作","topic":"年度政府工作","category":"时政","text":"5.海南自由贸易港启动全岛封关运作\n全岛封关运作是海南自贸港建设的标志性工程，是进一步扩大开放的重要举措。封关是\n指将海南岛全岛建成一个海关监管特殊区域，实施以“‘一线’放开、‘二线’管住、岛\n内自由”为基本特征的自由化便利化政策制度。\n“‘一线’放开”，是将海南自贸港与我国关境外其他国家和地区之间作为“一线”，\n实施一系列自由便利进出举措；“‘二线’管住”，是将海南自贸港与内地之间作为“二线”，\n针对“一线”放开的内容实施精准管理；“岛内自由”，是在海南自贸港内，各类要素可以\n相对自由流通。\n——中国政府网","source":{"doc":"6cbfb01fe723bba64b75","first":8,"last":9,"page":8,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"open","title":"高水平开放与经贸规则"}],"units":{"k-2dd879cdcaced5ff":[]}};
